def merge_sorted(a: list, b: list) -> list:
    """Merges two already-sorted lists into one sorted list."""
    result = []
    i = j = 0

    # Merge the two sorted lists
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1

   # Add remaining elements
    while i < len(a):
        result.append(a[i])
        i += 1

    while j < len(b):
        result.append(b[j])
        j += 1

    return result

def balanced(s: str) -> bool:
    stack = []
    brackets = {'(': ')', '[': ']', '{': '}'}
    for c in s:
        if c in brackets:
            stack.append(c)
        elif c in brackets.values():
            if not stack:
                return False
            if c == ')':
                if stack.pop() != '(':
                    return False
            elif c == ']':
                if stack.pop() != '[':
                    return False
            elif c == '}':
                if stack.pop() != '{':
                    return False
    return len(stack) == 0

def parse_version(v: str) -> tuple:
    if not v or not v.strip():
        raise ValueError("empty string")
    # Check for leading 'v' (lowercase) and remove it
    if v[0].lower() == 'v':
        v = v[1:]
    else:
        # Check for uppercase 'V' or other invalid characters
        if v[0].upper() == 'V':
            raise ValueError("uppercase 'V'")
        if not v[0].isdigit():
            raise ValueError("leading non-digit character")

    # Remove leading/trailing whitespace
    v = v.strip()
    if not v:
        raise ValueError("empty string after whitespace")

    # Check for any whitespace in the string
    if ' ' in v:
        raise ValueError("whitespace anywhere in the string")

    # Split by dots and validate each component
    parts = v.split('.')
    if len(parts) > 3:
        raise ValueError("a fourth component or more")

    # Each part must be digits only
    for part in parts:
        if not part.isdigit():
            raise ValueError("non-digit character")

    # Check that components are only digits and no other characters
    for i, part in enumerate(parts):
        if not part.isdigit():
            raise ValueError("non-digit character")
        if len(part) == 0:
            raise ValueError("empty component")

    # Process each component, defaulting missing ones to 0
    result = []
    for part in parts:
        if part:
            result.append(int(part))
        else:
            result.append(0)

    # Pad to three components
    if len(result) < 3:
        result.extend([0] * (3 - len(result)))

    if len(result) != 3:
        raise ValueError("excess components or missing components")

    return tuple(result)

def verdict(passed: bool, tokens: int, cap: int, closed_fence: bool) -> str:
    if not isinstance(cap, int) or cap < 1:
        raise ValueError("cap must be at least 1")
    if not isinstance(tokens, int) or tokens < 0:
        raise ValueError("tokens must be non-negative")
    if passed:
        return "PASS"
    if tokens >= cap:
        return "CUT"
    if not closed_fence:
        return "CUT"
    return "FAIL"

def rank_quants(names: list) -> list:
    def get_precision(name):
        if not name:
            return None
        # Extract first digit
        first_char = name[0]
        if first_char in '0123456789':
            return int(first_char)
        return None

    # Filter out names with no digit
    filtered_names = [name for name in names if get_precision(name) is not None]

    # Sort by precision (higher first), then by prefix (Q before IQ), then alphabetically
    def sort_key(name):
        precision = get_precision(name)
        prefix = name[0] if name[0] in 'QIQ' else None
        if prefix == 'Q':
            prefix_val = 0
        elif prefix == 'IQ':
            prefix_val = 1
        else:
            prefix_val = 100  # fallback
        return (-precision, (0 if prefix == 'Q' else 1) if prefix else 100, name)

    # Generate stable sort key
    sorted_names = sorted(filtered_names, key=lambda x: (
        -get_precision(x), 
        0 if x.startswith('Q') else 1, 
        x
    ))

    return sorted_names

def dominant_case(words: list[str]) -> str:
    if not words:
        return "none"

    count = {"upper": 0, "lower": 0, "mixed": 0}

    for word in words:
        has_upper = False
        has_lower = False

        # Check only letters
        for c in word:
            if c.isalpha():
                if c.isupper():
                    has_upper = True
                if c.islower():
                    has_lower = True

        if not has_upper and not has_lower:
            # no letters at all - ignore
            continue

        if has_upper and has_lower:
            count["mixed"] += 1
        elif has_upper:
            count["upper"] += 1
        elif has_lower:
            count["lower"] += 1

    # Tie-break: return first in order "upper", "lower", "mixed"
    max_count = max(count["upper"], count["lower"], count["mixed"])

    if count["upper"] == max_count:
        return "upper"
    elif count["lower"] == max_count:
        return "lower"
    else:
        return "mixed"

def chunk_sequence(items: list, size: int, policy: str, fill=None) -> list:
    if not items:
        return []

    if size <= 0:
        raise ValueError("size must be greater than 0")

    if policy not in ("keep", "drop", "pad"):
        raise ValueError(f"policy must be one of 'keep', 'drop', 'pad'; got {policy}")

    if len(items) % size == 0:
        # final chunk is exactly size, so policy doesn't apply
        return [items[i:i+size] for i in range(0, len(items), size)]

    # final chunk is shorter than size
    chunks = []
    for i in range(0, len(items) - (len(items) % size), size):
        chunks.append(items[i:i+size])

    # handle the short final chunk
    remainder = items[len(items) - (len(items) % size):]
    if policy == "keep":
        chunks.append(remainder)
    elif policy == "drop":
        pass  # do nothing, just skip the remainder
    elif policy == "pad":
        # pad with fill until length is size
        padded = remainder + [fill] * (size - len(remainder))
        chunks.append(padded)

    return chunks

