def validation_parse_range_spec(spec: str) -> list:
    if not spec or spec == "":
        raise ValueError("empty string")

    fields = spec.split(",")
    result = []

    for field in fields:
        field = field.strip()
        if not field:
            raise ValueError("empty field")

        # Check for valid characters and digits only
        if not field.isdigit():
            raise ValueError("non-digit characters in field")

        # Check for leading zeros except for "0"
        if field[0] == '0' and len(field) > 1:
            raise ValueError("leading zero")
        if field == "0":
            pass  # valid
        else:
            # Check for leading zeros in any case
            if field[0] == '0':
                raise ValueError("leading zero")

        # Check number size: 0 to 999 inclusive
        num = int(field)
        if num < 0 or num > 999:
            raise ValueError("number out of range 0-999")

        # Handle single number
        if "-" not in field:
            result.append(num)
        else:
            # Range: must have exactly one "-" and be surrounded by numbers
            parts = field.split("-")
            if len(parts) != 2:
                raise ValueError("range must have exactly two parts")
            lo, hi = parts[0], parts[1]
            if not lo.isdigit() or not hi.isdigit():
                raise ValueError("non-digit in range")
            lo_num = int(lo)
            hi_num = int(hi)

            # Check for valid range: lo < hi
            if lo_num >= hi_num:
                raise ValueError("lo must be strictly less than hi")
            if lo_num < 0 or hi_num > 999:
                raise ValueError("range values out of 0-999")

            # Ensure no duplicates in the range
            for val in range(lo_num, hi_num + 1):
                if val in result:
                    raise ValueError("duplicate value in range")
            result.extend(range(lo_num, hi_num + 1))

    # Check for duplicates in final list
    if len(result) != len(set(result)):
        raise ValueError("duplicate integer in result")

    return result

def clamp_and_count(values: list[int], low: int, high: int) -> tuple[list[int], int]:
    if not values:
        return [], 0

    if low > high:
        raise ValueError("low > high")

    clamped = []
    changed = 0

    for value in values:
        if value < low:
            clamped.append(low)
            changed += 1
        elif value > high:
            clamped.append(high)
            changed += 1
        else:
            clamped.append(value)

    return (clamped, changed)

def speed_to_kmh(meters: float, seconds: float) -> str:
    if seconds <= 0:
        raise ValueError("seconds must be positive")
    if meters < 0:
        raise ValueError("meters must be non-negative")
    speed_kmh = meters * 3.6 / seconds
    return f"{speed_kmh:.2f} km/h"

def stateful_classify_ticket(age_days: int, severity: str, subscriber: bool) -> str:
    # Validate inputs in order
    if age_days < 0:
        raise ValueError("age_days cannot be negative")
    if severity not in ["low", "medium", "high"]:
        raise ValueError("severity must be one of 'low', 'medium', 'high'")

    # Apply classification rules in specified order
    if severity == "high" and subscriber is True:
        return "escalate"
    if age_days > 30:
        return "archive"
    if severity == "high":
        return "urgent"
    if subscriber is True and age_days >= 7:
        return "review"
    return "queue"

def stateful_run_machine(events: list[str]) -> str:
    state = "idle"
    for event in events:
        if event not in ["start", "pause", "resume", "stop", "tick"]:
            raise ValueError(f"unrecognized event: {event}")
        if state == "stopped":
            state = "stopped"
        if event == "stop":
            state = "stopped"
        elif event == "start":
            state = "running"
        elif state == "running" and event == "pause":
            state = "paused"
        elif state == "paused" and event == "resume":
            state = "running"
        # otherwise, state remains unchanged
    return state

def parse_pipe_record(line: str) -> list[str]:
    if line == "":
        return [""]

    fields = []
    current_field = ""
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '|':
            if current_field:
                fields.append(current_field)
                current_field = ""
            i += 1
        elif line[i] == '\\' and i + 1 < n:
            if i + 1 < n:
                if line[i+1] == '|':
                    # \|
                    i += 2
                    current_field += '|'
                elif line[i+1] == '\\':
                    # \\
                    i += 2
                    current_field += '\\'
                elif line[i+1] == '\n':
                    # \n
                    i += 2
                    current_field += '\n'
                else:
                    # \ followed by any other character
                    raise ValueError("Invalid escape sequence")
            else:
                # backslash at end of line
                raise ValueError("Backslash at end of line")
        else:
            # any other character
            current_field += line[i]
            i += 1

        if i >= n:
            break

    if current_field:
        fields.append(current_field)
    else:
        # if we ended at a pipe, then we have one empty field
        fields.append("")

    if i < n:
        # we didn't parse the whole line
        raise ValueError("Incomplete parsing")

    # if there are two pipes in a row, it creates an empty field between them
    # so we need to adjust the field list accordingly
    # we do not reprocess, but instead just detect when two consecutive pipes occur
    # and insert an empty field between them

    # recompute the fields using the original parsing
    # we'll do this by reprocessing the line with proper pipe splitting
    result = []
    i = 0
    while i < n:
        if line[i] == '|':
            i += 1
            continue
        elif i >= n:
            break
        # find the next pipe or end
        j = i
        while j < n and line[j] != '|':
            j += 1
        if j == i:
            # no character between, just a pipe
            result.append("")
            i += 1
        else:
            # we found a field between pipes
            field = line[i:j]
            if field == "":
                # we have an empty field
                result.append("")
            else:
                # we have a non-empty field
                result.append(field)
            i = j

    # reprocess with correct field handling
    # split by pipes and collect fields
    fields = []
    i = 0
    while i < n:
        if i < n and line[i] == '|':
            i += 1
            continue
        else:
            # start of a new field
            j = i
            while j < n and line[j] != '|':
                j += 1
            if j == i:
                # empty field
                fields.append("")
            else:
                fields.append(line[i:j])
            i = j

    # now process any escape sequences in each field
    final_fields = []
    for field in fields:
        if field == "":
            final_fields.append("")
            continue
        if field == "||":
            # two pipes in a row
            final_fields.append("")
            continue
        # check for escape sequences
        # process each character in the field
        new_field = ""
        k = 0
        while k < len(field):
            if field[k] == '\\':
                k += 1
                if k >= len(field):
                    raise ValueError("Backslash at end of field")
                if field[k] == '|':
                    # \|
                    new_field += '|'
                    k += 1
                elif field[k] == '\\':
                    # \\
                    new_field += '\\'
                    k += 1
                elif field[k] == '\n':
                    # \n
                    new_field += '\n'
                    k += 1
                else:
                    # \ followed by invalid character
                    raise ValueError("Invalid escape sequence")
            else:
                new_field += field[k]
                k += 1
        if new_field == field:
            # no escapes found
            pass
        else:
            # we processed the field with escapes
            pass
    return final_fields

def parse_kv_config(line: str) -> dict[str, str]:
    if not line.strip():
        return {}
    result = {}
    segments = [seg.strip() for seg in line.split(';')]
    for seg in segments:
        if not seg.strip():
            continue
        parts = seg.split('=', 1)
        if len(parts) != 2:
            raise ValueError("Missing or malformed key-value pair")
        key, value = parts
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError("Empty key")
        # Strip only leading/trailing whitespace from key and value
        # Whitespace inside value is preserved
        result[key] = value
    return result

split_list() {
    [[ $# -eq 0 ]] && return 0
    IFS=',' read -ra items <<< "$(printf '%s\n' "$1")"
    for item in "${items[@]}"; do
        case "$item" in
            ''|' '*|* *|* **) continue ;;
        esac
        printf '%s\n' "$item"
    done
}

